/**
 * Where a build's pinned tables are. The importer's table constants are US rev 0's; another build's layout gives,
 * per table (`<set>.<table>`, the sets `platinum`, `anim`, `ui2d`), its offset, the SHA-1 it is checked by and, where
 * the build's table has another number of rows, the count. Layouts are generated by `pnpm relocate` (tools/relocate.ts).
 */
import { readHeader, SUPPORTED_ROMS, type RomLanguage, type SupportedRom } from '@opensinnoh/nds';
import { LAYOUT as PLATINUM_DE } from './layouts/platinum-de.ts';

/** What differs between the supported builds: the tables' places and where the localized files are. */
export interface RomBuild {
  rom: SupportedRom;
  layout: Layout;
  /** US path → this build's path (NitroFs `paths`), for the files a localized build keeps elsewhere. */
  paths: Readonly<Record<string, string>>;
}

/**
 * The German build keeps its localized graphics (the ones with text drawn in) in `/resource/ger/<folder>/`; the US
 * build has some in `/resource/eng/` and the rest in the general folders. Measured on CPUD rev 0.
 */
const GERMAN_PATHS: Readonly<Record<string, string>> = Object.fromEntries(
  [
    ['/battle/graphic/pl_batt_obj.narc', 'battle_graphic/pl_batt_obj.narc'],
    ['/contest/graphic/contest_bg.narc', 'contest_graphic/contest_bg.narc'],
    ['/contest/graphic/contest_obj.narc', 'contest_graphic/contest_obj.narc'],
    ['/data/namein.narc', 'nameinput/namein.narc'],
    ['/data/slot.narc', 'slot/slot.narc'],
    ['/demo/title/titledemo.narc', 'title/titledemo.narc'],
    ['/fielddata/pokemon_trade/fld_trade.narc', 'pokemon_trade/fld_trade.narc'],
    ['/graphic/box.narc', 'box/box.narc'],
    ['/graphic/imageclip.narc', 'dress_up_graphic/imageclip.narc'],
    ['/graphic/nutmixer.narc', 'nutmixer/nutmixer.narc'],
    ['/graphic/pl_bag_gra.narc', 'bag/pl_bag_gra.narc'],
    ['/graphic/pl_plist_gra.narc', 'pokelist/pl_plist_gra.narc'],
    ['/graphic/pl_pst_gra.narc', 'p_status/pl_pst_gra.narc'],
    ['/graphic/poketch.narc', 'poketch/poketch.narc'],
    ['/graphic/touch_subwindow.narc', 'touch_subwindow/touch_subwindow.narc'],
    ['/graphic/trainer_case.narc', 'trainer_case/trainer_case.narc'],
    ['/resource/eng/zukan/zukan.narc', 'zukan/zukan.narc'],
    ['/resource/eng/frontier_graphic/frontier_bg.narc', 'frontier_graphic/frontier_bg.narc'],
    ['/resource/eng/frontier_graphic/frontier_obj.narc', 'frontier_graphic/frontier_obj.narc'],
  ].map(([us, de]) => [us, `/resource/ger/${de}`]),
);

const PATHS: Readonly<Record<RomLanguage, Readonly<Record<string, string>>>> = { en: {}, de: GERMAN_PATHS };

export function romBuild(rom: SupportedRom): RomBuild {
  return { rom, layout: layoutOf(rom.id), paths: PATHS[rom.language] };
}

/** The build of ROM bytes whose header names a supported Platinum (tests and tools; the importer checks the SHA-1). */
export function romBuildOfHeader(rom: Uint8Array): RomBuild {
  const h = readHeader(rom);
  const matches = Object.values(SUPPORTED_ROMS).filter((r) => r.gameCode === h.gameCode && r.revision === h.version);
  if (matches.length !== 1) throw new Error(`no supported Platinum build has game code ${h.gameCode} revision ${h.version}`);
  return romBuild(matches[0]!);
}

export interface PinPlace {
  offset: number;
  sha1: string;
  count?: number;
}

export type Layout = Readonly<Record<string, PinPlace>>;

/** By SupportedRom id; US rev 0 is the constants themselves. */
const LAYOUTS: Readonly<Record<string, Layout>> = {
  'platinum-us-rev0': {},
  'platinum-de-rev0': PLATINUM_DE,
};

export function layoutOf(romId: string): Layout {
  const layout = LAYOUTS[romId];
  if (!layout) throw new Error(`no table layout for ROM ${romId}`);
  return layout;
}

type Placed<V> = { [P in keyof V]: P extends 'offset' | 'count' ? number : P extends 'sha1' ? string : V[P] };

/** `tables` (one set's US constants) with the layout's places for `set` applied; a layout key the set lacks fails. */
export function placeTables<T extends Record<string, { offset: number; sha1: string }>>(tables: T, layout: Layout, set: string): { [K in keyof T]: Placed<T[K]> } {
  for (const key of Object.keys(layout)) {
    const [s, name] = key.split('.');
    if (s === set && !(name! in tables)) throw new Error(`layout: ${key} is not a ${set} table`);
  }
  return Object.fromEntries(
    Object.entries(tables).map(([name, t]) => {
      const place = layout[`${set}.${name}`];
      if (!place) return [name, t];
      if (place.count !== undefined && !('count' in t)) throw new Error(`layout: ${set}.${name} has no count to change`);
      return [name, { ...t, offset: place.offset, sha1: place.sha1, ...(place.count === undefined ? {} : { count: place.count }) }];
    }),
  ) as { [K in keyof T]: Placed<T[K]> };
}
